    if ((body_vectors == NULL) || (predicted_body_vectors == NULL) || 
        (weights == NULL) || (rms_rad == NULL)) {
        if (rms_rad != NULL) *rms_rad = 0.0;
        return ADCS_E_NULL;
    }
    if (count < 1U || count > 32U) {
        *rms_rad = 0.0;
        return ADCS_E_RANGE;
    }

    double sum_w_theta_sq = 0.0;
    double sum_w = 0.0;
    adcs_vec3_t bn, pn;
    size_t i;

    for (i = 0; i < count; i++) {
        if (adcs_vec3_normalize(&body_vectors[i], ADCS_EPS_NORM, &bn) != ADCS_OK) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }
        if (adcs_vec3_normalize(&predicted_body_vectors[i], ADCS_EPS_NORM, &pn) != ADCS_OK) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }

        double dot = adcs_vec3_dot(&bn, &pn);
        double clamped_dot = ADCS_CLAMP(dot, -1.0, 1.0);
        double theta = acos(clamped_dot);
        double w = weights[i];

        if (!isfinite(w) || w <= 0.0) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }

        sum_w_theta_sq += w * theta * theta;
        sum_w += w;
    }

    if (sum_w <= FLT64_ZERO) {
        *rms_rad = 0.0;
        return ADCS_E_DEGENERATE;
    }

    *rms_rad = sqrt(sum_w_theta_sq / sum_w);
    return ADCS_OK;
}

